        : children_(std::move(children)) {
        for (const auto& child : children_) {
            if (!child) {
                throw std::invalid_argument(
                    "child");
            }
        }
    } // End group construction.
    int minutes() const override {
        // Add each child subtotal once.
        int total = 0;
        for (const auto& child : children_) {
            const int n = child->minutes();
